use std::collections::HashMap
use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    let mut out: Vec<string> = []
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0]
        if cmd == "balance" {
            if p.len() < 2 { continue }
            match acc.get(p[1]) {
                Some(b) => out.push("${b}"),
                None => out.push("error: unknown account ${p[1]}"),
            }
        } else if cmd == "open" {
            if p.len() < 3 { continue }
            let amt: int = p[2].parse::<int>().unwrap_or(-1)
            if amt < 0 {
                out.push("error: invalid amount")
            } else if acc.contains_key(p[1]) {
                out.push("error: duplicate account")
            } else {
                acc.insert(p[1], amt)
                out.push("ok")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            if p.len() < 3 { continue }
            let amt: int = p[2].parse::<int>().unwrap_or(-1)
            if amt <= 0 {
                out.push("error: invalid amount")
            } else {
                match acc.get(p[1]) {
                    None => out.push("error: unknown account ${p[1]}"),
                    Some(b) => {
                        if cmd == "deposit" {
                            acc.insert(p[1], b + amt)
                            out.push("ok")
                        } else if b < amt {
                            out.push("error: insufficient funds")
                        } else {
                            acc.insert(p[1], b - amt)
                            out.push("ok")
                        }
                    }
                }
            }
        } else if cmd == "transfer" {
            if p.len() < 4 { continue }
            let amt: int = p[3].parse::<int>().unwrap_or(-1)
            if amt <= 0 {
                out.push("error: invalid amount")
            } else if !acc.contains_key(p[1]) {
                out.push("error: unknown account ${p[1]}")
            } else if !acc.contains_key(p[2]) {
                out.push("error: unknown account ${p[2]}")
            } else if p[1] == p[2] {
                out.push("error: same account")
            } else {
                let fb: int = acc.get(p[1]).unwrap_or(0)
                let tb: int = acc.get(p[2]).unwrap_or(0)
                if fb < amt {
                    out.push("error: insufficient funds")
                } else {
                    acc.insert(p[1], fb - amt)
                    acc.insert(p[2], tb + amt)
                    out.push("ok")
                }
            }
        }
    }
    let mut keys: Vec<string> = acc.keys().map(|k| k.to_string()).collect()
    keys.sort()
    for k in keys {
        let b: int = acc.get(k).unwrap_or(0)
        out.push("${k} ${b}")
    }
    for l in out {
        println(l)
    }
}

